// Um item por lead em conversa; pula os que o Hamilton pausou no copiloto (wf02.pausado = true)
// e os que seguem por outro canal (ex.: wf01.etapa = aguardando_resposta_email)
const out = [];
for (const item of $input.all()) {
  const l = item.json || {};
  if (!l.id) continue;
  const cf = (l.custom_fields && typeof l.custom_fields === 'object') ? l.custom_fields : {};
  const wf02 = cf.wf02 || {};
  const wf01 = cf.wf01 || {};
  if (wf02.pausado === true) continue;
  if (/email/i.test(String(wf01.etapa || ''))) continue;
  const c = l.contacts || {};
  out.push({ json: {
    lead_id: l.id,
    contact_id: l.contact_id,
    stage_id: l.stage_id,
    empresa: String(c.name || '').trim(),
    telefone: String(c.phone_number || '').replace(/\D/g, ''),
    wf01,
    wf02
  } });
}
return out;

// Decide quais leads precisam de sugestão agora e monta o pedido para o Claude.
// modo 'resposta': o lead mandou mensagem e ninguém respondeu ainda.
// modo 'followup': a última mensagem é nossa e o lead sumiu (1º lembrete em 24h, 2º 48h depois, no máximo 2).
const LINK_AGENDA = 'https://calendar.app.google/nTdCMvHLeZo7eLLL8';
const MODELO = 'claude-opus-5-5';
const MAX_POR_EXECUCAO = 3;
const H = 3600 * 1000;
const NL = String.fromCharCode(10);
const agora = Date.now();
const ETAPAS = {
  '03dea7bf-9c4d-4f22-98b2-0fd7aa27f9f8': 'Em Qualificação',
  '4c26d63e-606d-49d9-8daf-fd5c4e8c7f55': 'Lead Quente'
};
const fmt = (ts) => new Date(ts).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const corpo = (m) => {
  const b = String(m.body || '').trim();
  if (b) return b;
  return '[' + (m.type || 'mídia') + ' sem texto]';
};

const leads = $('Code - Normalizar Leads').all().map(i => i.json);
const msgs = $input.all().map(i => i.json).filter(m => m && m.id && m.contact_id);

const SYSTEM = [
  'Você escreve mensagens de WhatsApp em nome do Hamilton, da Agência OnlineAgora, para donos e atendentes de negócios locais (farmácias de manipulação, clínicas, studios, lojas) que já responderam a uma prospecção dele.',
  '',
  'O que o Hamilton oferece: automação no WhatsApp do próprio negócio para não perder cliente. Exemplos: quem pediu orçamento e sumiu recebe um retorno automático no tempo certo (no mesmo dia ou no dia seguinte, perguntando se ficou dúvida); lembretes quando algo fica pronto; quem demonstra interesse cai direto para a equipe responder; e o negócio passa a ver quantos orçamentos viraram venda depois do lembrete. Funciona com o processo que eles já têm, só tira a dependência de alguém lembrar.',
  '',
  'Objetivo da conversa: marcar uma conversa de 15 minutos com o Hamilton. Link para o lead escolher o horário: ' + LINK_AGENDA,
  '',
  'Regras de escrita:',
  '- Português do Brasil, tom humano, simpático e direto, como o Hamilton escreveria no celular. Nada de linguagem de vendedor ou de robô.',
  '- Curto: no máximo 3 frases curtas, em até 2 parágrafos. No máximo 1 emoji.',
  '- Responda primeiro ao que a pessoa disse ou perguntou. Valorize o que ela já faz bem antes de propor algo.',
  '- Termine com uma pergunta simples ou com o convite para os 15 minutos.',
  '- Mande o link da agenda quando a pessoa mostrar abertura (confirmou a dor, perguntou como funciona, perguntou preço, pediu proposta). Não mande o link duas vezes seguidas se ele já foi enviado e a pessoa não reagiu a ele; nesse caso ofereça também "ou me diz um horário que eu encaixo".',
  '- Nunca fale preço, prazo ou valores. Se perguntarem, diga que depende do volume e do jeito que eles atendem, e que nos 15 minutos o Hamilton mostra e passa os valores.',
  '- Nunca invente números, casos de clientes, resultados, integrações ou garantias. Nunca critique o robô, o atendimento ou o processo deles.',
  '- Não se apresente de novo se o Hamilton já se apresentou na conversa. Não diga que é uma IA.',
  '',
  'Quando NÃO sugerir mensagem (acao = "avisar_hamilton"): pedido de contrato, proposta formal por escrito, dúvida técnica específica (integração com sistema X, API, LGPD), reclamação, assunto pessoal, pedido para falar por ligação agora, ou qualquer coisa que você não saiba responder com segurança.',
  'Quando acao = "nada": a última mensagem do lead não pede resposta (ex.: só "ok", "👍", figurinha) e o Hamilton já fez a pergunta ou o convite.',
  '',
  'etapa_sugerida: "agendado" se o lead disse que marcou ou combinou horário; "lead_quente" se pediu preço, proposta ou demonstrou interesse claro; "descartado" se disse que não tem interesse; senão "manter".',
  'motivo: uma frase curta, para o Hamilton, explicando a leitura da conversa.'
].join(NL);

const out = [];
for (const l of leads) {
  if (out.length >= MAX_POR_EXECUCAO) break;
  const ms = msgs.filter(m => m.contact_id === l.contact_id)
    .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
  if (!ms.length) continue;
  const wf2 = l.wf02 || {};
  const last = ms[ms.length - 1];
  const lastTs = new Date(last.created_at).getTime();
  const inbounds = ms.filter(m => m.direction === 'inbound');
  const lastIn = inbounds[inbounds.length - 1];
  if (!lastIn) continue; // lead nunca respondeu: não é conversa
  let modo = null;
  let fu = { anchor: null, count: 0 };
  if (last.direction === 'inbound') {
    if (agora - lastTs < 90 * 1000) continue; // espera o lead terminar de digitar
    if (agora - lastTs > 12 * H) continue;   // resposta velha demais: o Hamilton resolve
    if (wf2.ultima_inbound_processada === last.id) continue;
    modo = 'resposta';
  } else {
    const count = (wf2.fu_anchor === lastIn.id) ? Number(wf2.fu_count || 0) : 0;
    if (count >= 2) continue;
    const ref = count === 0 ? lastTs : Math.max(lastTs, new Date(wf2.fu_ultimo_em || 0).getTime());
    const espera = count === 0 ? 24 * H : 48 * H;
    if (agora - ref < espera) continue;
    if (agora - lastTs > 10 * 24 * H) continue; // conversa parada há mais de 10 dias: não insiste
    modo = 'followup';
    fu = { anchor: lastIn.id, count };
  }

  const historico = ms.slice(-30).map(m => '[' + fmt(m.created_at) + '] ' + (m.direction === 'inbound' ? 'Lead' : 'Hamilton') + ': ' + corpo(m)).join(NL + NL);
  const linkJaEnviado = ms.some(m => m.direction === 'outbound' && String(m.body || '').includes('calendar.app.google'));
  let tarefa;
  if (modo === 'resposta') {
    tarefa = 'Escreva a próxima mensagem do Hamilton respondendo ao lead.';
  } else if (fu.count === 0) {
    tarefa = 'O lead não responde há mais de 24 horas. Escreva o 1º lembrete (follow-up): leve, retomando o último assunto em poucas palavras. ' + (linkJaEnviado ? 'O link da agenda já foi enviado: lembre dele e ofereça também que a pessoa diga um horário que o Hamilton encaixa.' : 'Convide para os 15 minutos com o link da agenda.');
  } else {
    tarefa = 'O lead continua sem responder, mesmo depois de um lembrete. Escreva o 2º e último lembrete: bem curto, sem pressão, deixando a porta aberta (ex.: fica à vontade, quando fizer sentido é só me chamar) e repetindo o link da agenda.';
  }
  const user = [
    'Agora: ' + fmt(agora),
    'Empresa: ' + (l.empresa || '(sem nome)'),
    'Etapa no CRM: ' + (ETAPAS[l.stage_id] || 'em conversa'),
    'Link da agenda já enviado nesta conversa: ' + (linkJaEnviado ? 'sim' : 'não'),
    '',
    'Conversa no WhatsApp (mais antiga primeiro):',
    historico,
    '',
    'Tarefa: ' + tarefa
  ].join(NL);

  const body = {
    model: MODELO,
    max_tokens: 4000,
    output_config: {
      effort: 'medium',
      format: { type: 'json_schema', schema: {
        type: 'object',
        properties: {
          acao: { type: 'string', enum: ['sugerir', 'avisar_hamilton', 'nada'] },
          texto: { type: 'string', description: 'A mensagem pronta para enviar ao lead (vazia se acao não for sugerir).' },
          motivo: { type: 'string' },
          etapa_sugerida: { type: 'string', enum: ['manter', 'lead_quente', 'agendado', 'descartado'] }
        },
        required: ['acao', 'texto', 'motivo', 'etapa_sugerida'],
        additionalProperties: false
      } }
    },
    fallbacks: 'default',
    system: SYSTEM,
    messages: [{ role: 'user', content: user }]
  };

  let tel = l.telefone;
  if (tel && !tel.startsWith('55')) tel = '55' + tel;
  out.push({ json: {
    lead_id: l.lead_id,
    contact_id: l.contact_id,
    empresa: l.empresa,
    telefone: tel,
    chatId: tel + '@c.us',
    conversation_id: last.conversation_id,
    channel_session_id: (ms.slice().reverse().find(m => m.channel_session_id) || {}).channel_session_id || null,
    modo,
    fu_anchor: fu.anchor,
    fu_count: fu.count,
    ultima_msg_id: last.id,
    ultima_msg_em: last.created_at,
    ultima_do_lead: corpo(lastIn).substring(0, 300),
    claude_body: JSON.stringify(body)
  } });
}
return out;

// Lê a resposta do Claude, grava a sugestão pendente (com token de uso único) e marca o lead como processado.
const NL = String.fromCharCode(10);
const d = $('Code - Decidir').item.json;
const r = $('Claude - Sugerir Resposta').item.json || {};
const atual = $json || {};
const cf = (atual.custom_fields && typeof atual.custom_fields === 'object') ? atual.custom_fields : null;
if (!cf) return { json: { pular: true, motivo: 'lead_nao_lido' } };
const prev = cf.wf02 || {};
const agora = new Date().toISOString();

let s = null;
let erro = '';
if (r.error) erro = 'erro_api: ' + String((r.error && r.error.message) || JSON.stringify(r.error)).substring(0, 200);
else if (r.stop_reason === 'refusal') erro = 'recusa_do_modelo';
else {
  const blocos = (r.content || []).filter(b => b.type === 'text');
  const txt = blocos.length ? blocos[blocos.length - 1].text : '';
  try { s = JSON.parse(txt); } catch (e) { erro = 'resposta_invalida'; }
}
if (s && s.acao === 'sugerir' && !String(s.texto || '').trim()) { s.acao = 'avisar_hamilton'; s.motivo = 'sugestão veio vazia'; }
const acao = erro ? 'erro' : s.acao;

const wf02 = Object.assign({}, prev, { ultima_execucao_em: agora });
if (d.modo === 'resposta') wf02.ultima_inbound_processada = d.ultima_msg_id;
else { wf02.fu_anchor = d.fu_anchor; wf02.fu_count = Number(d.fu_count || 0) + 1; wf02.fu_ultimo_em = agora; }

let token = '';
let link = '';
if (acao === 'sugerir') {
  while (token.length < 32) token += Math.random().toString(36).slice(2);
  token = token.slice(0, 32);
  wf02.pendente = {
    token, texto: String(s.texto).trim(), modo: d.modo, fu_n: d.modo === 'followup' ? Number(d.fu_count || 0) + 1 : 0,
    etapa_sugerida: s.etapa_sugerida, motivo: s.motivo,
    chatId: d.chatId, telefone: d.telefone, empresa: d.empresa,
    conversation_id: d.conversation_id, channel_session_id: d.channel_session_id, contact_id: d.contact_id,
    ultima_msg_em: d.ultima_msg_em, criado_em: agora
  };
  link = 'https://webhook.hamiltonviana.com.br/webhook/wf02-copiloto?lead=' + d.lead_id + '&t=' + token;
}
const rotulo = d.modo === 'resposta' ? 'resposta' : ('follow-up ' + (Number(d.fu_count || 0) + 1) + '/2');
const nota = '[' + agora + '] WF02 copiloto (' + rotulo + '): ' + (erro ? erro : (acao + ' - ' + (s.motivo || '')));
wf02.log = ((prev.log || '') + NL + nota).trim().split(NL).slice(-30).join(NL);
const novo = Object.assign({}, cf, { wf02 });

const ETAPA = { manter: 'manter', lead_quente: 'Lead Quente', agendado: 'Agendado', descartado: 'Descartado' };
const empresa = d.empresa || d.telefone;
let aviso = '';
if (acao === 'sugerir') {
  aviso = '💬 Copiloto: ' + empresa + ' (' + rotulo + ')' + NL + NL
    + (d.modo === 'resposta' ? 'Lead disse: "' + d.ultima_do_lead + '"' : 'Sem resposta do lead desde a sua última mensagem.') + NL + NL
    + 'Sugestão (ainda NÃO enviada):' + NL + NL + String(s.texto).trim() + NL + NL
    + '👉 Revisar, editar e enviar pelo 2144:' + NL + link + NL + NL
    + 'Leitura: ' + (s.motivo || '') + (s.etapa_sugerida && s.etapa_sugerida !== 'manter' ? NL + 'Etapa sugerida no CRM: ' + ETAPA[s.etapa_sugerida] : '') + NL
    + 'Se você responder antes pelo celular, a sugestão é descartada.';
} else if (acao === 'avisar_hamilton') {
  aviso = '⚠️ Copiloto: ' + empresa + ' precisa de você' + NL + NL
    + 'Lead disse: "' + d.ultima_do_lead + '"' + NL + NL + 'Por quê: ' + (s.motivo || '') + NL + NL + 'Nenhuma sugestão foi gerada. Responda pelo celular.';
} else if (acao === 'erro') {
  aviso = '⚠️ Copiloto: não consegui gerar sugestão para ' + empresa + ' (' + erro + '). Responda pelo celular.';
}
return { json: { lead_id: d.lead_id, acao, avisar: aviso !== '', aviso, patch_body: JSON.stringify({ custom_fields: novo }) } };
